package com.threatstream.detection;
import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class NetworkDetectionEngineTest { private final DetectionProperties auth=new DetectionProperties("a","b","d",3,Duration.ofMinutes(10),new DetectionProperties.RuleConfig(10,Duration.ofMinutes(1)),new DetectionProperties.RuleConfig(10,Duration.ofMinutes(1)),new DetectionProperties.RuleConfig(5,Duration.ofMinutes(5))); private final NetworkDetectionProperties net=new NetworkDetectionProperties("n",100,new NetworkDetectionProperties.PortScan(3,Duration.ofMinutes(1),Duration.ofMinutes(1)),new NetworkDetectionProperties.Rate(1000,1000,Duration.ofMinutes(1),Duration.ofMinutes(1)),new NetworkDetectionProperties.Distributed(200,2,Duration.ofMinutes(1),Duration.ofMinutes(1)));
 private NetworkEvent event(String source,String target,int port,double bytes,int second){return new NetworkEvent(UUID.randomUUID(),"NETWORK_FLOW",1,Instant.parse("2026-01-01T00:00:00Z").plusSeconds(second),source,target,10,port,"6",1L,1L,1L,bytes,bytes,"cic-ids2017-replay");}
 private NetworkDetectionEngine engine(AlertPublisher publisher){return new NetworkDetectionEngine(new NetworkEventValidator(),new EventDeduplicator(auth),publisher,net,new AlertFactory());}
 @Test void port_scan_threshold_and_cooldown(){var p=mock(AlertPublisher.class);var e=engine(p);e.process(event("1.1.1.1","2.2.2.2",1,1,1));e.process(event("1.1.1.1","2.2.2.2",2,1,2));e.process(event("1.1.1.1","2.2.2.2",3,1,3));e.process(event("1.1.1.1","2.2.2.2",4,1,4));verify(p,times(1)).publish(any());}
 @Test void ddos_requires_source_diversity(){var p=mock(AlertPublisher.class);var e=engine(p);e.process(event("1.1.1.1","2.2.2.2",1,150,1));verifyNoInteractions(p);e.process(event("3.3.3.3","2.2.2.2",1,150,2));verify(p,atLeastOnce()).publish(any());}
}
